def test_hedge_sync_max_tries_forwarded():
    # max_tries=1 limits retries inside each hedged worker; use a target that
    # fails once. With max_tries=1 there is a single attempt per worker, so the
    # worker raises. Compare with max_tries=2 which retries.
    state = {"n": 0}

    def target():
        state["n"] += 1
        if state["n"] == 1:
            raise ValueError("first")
        return "second"

    # max_tries=1 => one attempt per worker => the first attempt fails and
    # whether we retry depends on max_tries. With max_tries=2 the retry should
    # succeed eventually within a single worker.
    result = hedge(target, _zero_wait, max_hedge=1, max_tries=2)
    assert result == "second"


