def test_hedge_sync_jitter_forwarded():
    # jitter stamps each backoff. With a failing target and max_tries=2 we can
    # detect the jitterer being consulted by using a sentinel that returns a
    # fixed value; but simplest is to assert jitter=None is accepted and that a
    # custom jitter is invoked.
    seen = []

