def test_hedge_sync_and_async_use_separate_wait_gens():
    used = {"sync": 0, "async": 0}

    def sync_wait(*a, **k):
        used["sync"] += 1

        def gen():
            while True:
                yield 0.0

        return gen()

    def async_wait(*a, **k):
        used["async"] += 1

        def gen():
            while True:
                yield 0.0

        return gen()

    def sync_target():
        return 1

    async def async_target():
        return 2

    assert hedge(sync_target, sync_wait, max_hedge=1, max_tries=2) == 1
    assert _run(hedge(async_target, async_wait, max_hedge=1, max_tries=2)) == 2
    assert used["sync"] == 1
    assert used["async"] == 1


